window.LD=window.LD||{};window.LD["party/p1"]={"id":"p1","name":"The Lantern of Carrbridge","poss":"The Lantern of Carrbridge's","members":["h4","h18","h12"],"leader":"h4","morale":83,"disposition":"wary","motto":"The night has eyes.","banner":{"c1":"#e8823a","c2":"#e8823a","emblem":"lantern"},"loc":"ashveil_crypts","loc_name":"The Ashveil Crypts","goal":{"text":"to find a relic of the old world","kind":"relic","done":null,"progress":"still looking","missed":true,"crew":"The Lantern of Carrbridge","party":"p1"},"vows":[{"text":"to die rich","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Lantern of Carrbridge","party":"p1"}],"doing":"last seen delving into The Ashveil Crypts","progress":null,"today":["Coin between them: -15 silver (thieves 12, omens 3).","Ate 7 rations.","Used up 4 torches."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":257,"season":{"wins":12,"bosses":0,"floors":9,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":4},"career":{"wins":26,"bosses":1,"floors":26,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":7},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"ox_wagon","name":"Second Chance","label":"ox wagon","seats":5,"haul":70,"comfort":0,"since":28,"desc":"Slow as a wedding, carries a house.","moves":true,"puller":{"kind":"ox","name":"Old Faithful","label":"ox","colour":"red","owner":null},"paid":[["Isolde",33],["Ash",23],["Pickles",8]]},"pace_gap":0,"rels":[{"party":"p3","score":100},{"party":"p2","score":20},{"party":"p5","score":13}],"events":[{"id":"e28","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Pickles and Isolde shake on it at The Honest Toll: they are now The Lantern of Carrbridge. (Wary, by the look of them.)","heroes":["h4","h18"],"parties":["p1"],"loc":"carrbridge","wx":"storm"},{"id":"e664","day":20,"season":1,"sday":20,"kind":"curse","imp":4,"text":"Something is wrong with The Lantern of Carrbridge. Since Pickles picked up the Hound's Collar, nobody trusts anybody, and Pickles won't put it down.","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e667","day":20,"season":1,"sday":20,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a cautious pace: 3 rooms (the grave-goods store, the reliquary, the reliquary passage).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":3,"size":3,"floor":3,"traps":1,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e668","day":20,"season":1,"sday":20,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts, 5 days on: The Lantern of Carrbridge comes up blinking at the daylight. They put 28% of it on paper, reached the deepest floor, turned up the weeping room, a hidden room behind the weeping room, the chapel of statues and 4 more good rooms, worked through 13 rooms, came away with 137 silver between them and turned back because their nerves were fraying. The Ashveil Crypts is mostly explored (69%), going by everyone's notes.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","days":5,"bottom":true,"rooms":["the weeping room","a hidden room behind the weeping room"],"gold":137,"turn":"nerve","wx":"fog"},{"id":"e688","day":20,"season":1,"sday":20,"kind":"boss_race","imp":2,"text":"The race for Vessimir the Unburied is one crew lighter: The Lantern of Carrbridge turned for other work. That leaves The Gravediggers of Ironhaven.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e706","day":20,"season":1,"sday":20,"kind":"goal_progress","imp":2,"text":"The Lantern of Carrbridge is getting close: earn 300 silver between them before the season ends (234 of 300 silver).","heroes":["h4","h18","h12"],"parties":["p1"]},{"id":"e708","day":21,"season":1,"sday":21,"kind":"night_game","imp":2,"text":"The bandit captain steps out on the road to Ashfen with a hopeful expression and a well-worn set of Highway Gambit, and nobody can quite bring themselves to draw a blade. The crew pays a gem for the privilege of losing at Highway Gambit, and the bandit captain is delighted, in a dignified way. Ash says nobody has ever been so politely held up, and is not sure how to feel about it.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashfen","night":"n32","monster_game":"bandit_captain","wx":"fog"},{"id":"e740","day":21,"season":1,"sday":21,"kind":"goal_done","imp":4,"text":"GOAL: The Lantern of Carrbridge set out to earn 300 silver between them before the season ends, and they have done it, with 9 days to spare. It was Pickles's idea in the first place. XP: Pickles +960 (level 10!), Isolde +960 (level 10!), Ash +960 (level 10!).","heroes":["h4","h18","h12"],"parties":["p1"],"xp":{"h4":960,"h18":960,"h12":960}},{"id":"e754","day":22,"season":1,"sday":22,"kind":"gift","imp":2,"text":"Pickles gets Ash's old Cape. \"Still good,\" says Ash. It is, mostly.","heroes":["h12","h4"],"parties":["p1"],"loc":"ashfen","wx":"fog"},{"id":"e755","day":22,"season":1,"sday":22,"kind":"map_bought","imp":2,"text":"The Lantern of Carrbridge buys a map of the Ashveil Crypts in Ashfen for 23 silver, drawn by Sela. The place is mostly explored (69%).","heroes":["h4","h18","h12","h2"],"parties":["p1"],"loc":"ashfen","wx":"fog"},{"id":"e757","day":22,"season":1,"sday":22,"kind":"ambush","imp":2,"text":"Three Wolves make the mistake of going for the Lantern of Carrbridge on the road to the Ashveil Crypts. The last wolf doesn't stay to see the end. The hit of the day was Isolde's Cleave on the wolf. Ash kept everyone standing (18 healed). Pickles insisted on checking every corner twice. Annoying. Correct. \"I'm fine. I'm fine. I'm not fine,\" says Pickles. Loot: 3 fangs & claws, a wolf haunch.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"kingsroad","fight":"f54","foes":["wolf","wolf","wolf"],"where":"on the road to The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-45},{"id":"e758","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Ash plays the bone flute after supper. Four notes, one of them always a surprise.","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e786","day":22,"season":1,"sday":22,"kind":"tarot","imp":2,"text":"Nobody sleeps until Isolde has read for The Lantern of Carrbridge. The night before the Ashveil Crypts, three cards: the Ace of Pentacles, the Nine of Wands and the Two of Wands. Isolde smiles at the last card.","heroes":["h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","reading":"r172","wx":"fog"},{"id":"e790","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Isolde shares supper with two pilgrims and their goat. The goat eats Pickles's bootlace. That's The Pilgrims' Escort for you.","heroes":["h18","h4"],"parties":["p1"],"loc":"ashveil_crypts","skill":"pilgrims_escort","wx":"fog"},{"id":"e805","day":23,"season":1,"sday":23,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into the Ashveil Crypts, mostly explored (71%), map in hand.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e819","day":23,"season":1,"sday":23,"kind":"talent","imp":2,"text":"Pickles counts heads at camp. Twice. Then a third time, under her breath. Not On My Watch, the guild calls it.","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts","skill":"not_on_my_watch","wx":"fog"},{"id":"e831","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a cautious pace: 1 room (the iron-bound door).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e846","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"A spiked trap springs on Ash. The spikes bend. Ash makes a small note for later. Chalk it up to Hard to Dent.","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","skill":"hard_to_dent","wx":"fog"},{"id":"e859","day":25,"season":1,"sday":25,"kind":"gear","imp":3,"text":"In a sealed space off the necromancer's workroom on floor 3 of the Ashveil Crypts, Ash finds a Grave-Blessed Chainmail and puts it on. Grave-Blessed: much braver (+7 nerve). It is a step up from anything Ash could buy.","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e860","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a steady pace: 2 rooms (the necromancer's workroom, a sealed space off the necromancer's workroom).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e861","day":25,"season":1,"sday":25,"kind":"delve_done","imp":1,"text":"The Ashveil Crypts gives up The Lantern of Carrbridge after 3 days, a little reluctantly, like a cat letting go of a sock. They cleared 3 rooms, reached the deepest floor, turned up a sealed space off the necromancer's workroom, put 60% of it on paper, came away with 53 silver between them and turned back because they were down to the last torch. The Ashveil Crypts, all crews together: mostly explored (75%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","days":3,"bottom":true,"rooms":["a sealed space off the necromancer's workroom"],"gold":53,"turn":"dark","wx":"fog"},{"id":"e930","day":27,"season":1,"sday":27,"kind":"curse","imp":2,"text":"Another bad night for The Lantern of Carrbridge. The Hound's Collar hums when Pickles sleeps. Nobody else sleeps at all.","heroes":["h4"],"parties":["p1"],"loc":"ashfen","wx":"fog"},{"id":"e943","day":27,"season":1,"sday":27,"kind":"ambush","imp":3,"text":"In the middle of the night, 2 Wolves and a Bandit Captain find the Lantern of Carrbridge's camp on the road to Carrbridge, and the Lantern of Carrbridge defeats them. Ash ended it the plain way: Anvil Drop, and the bandit captain on the ground. Oath of Light did more for this fight than the scoreboard shows. That was Isolde. Ash and Clementine the cat found the way out together. Loot: 35 silver each, 1 pelt, 2 wolf haunches.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"kingsroad","fight":"f65","foes":["wolf","bandit_captain","wolf"],"where":"at their camp on the road to Carrbridge, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-34},{"id":"e948","day":27,"season":1,"sday":27,"kind":"talent","imp":1,"text":"Isolde preaches to a field of sheep for practice. The sheep are an easy room.","heroes":["h18"],"parties":["p1"],"loc":"ashfen","skill":"sermoniser","wx":"fog"},{"id":"e965","day":28,"season":1,"sday":28,"kind":"wagon","imp":3,"text":"The Lantern of Carrbridge buys an ox wagon in Carrbridge for 64 silver. It's called Second Chance now. Who paid: Isolde 33, Ash 23, Pickles 8.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"carrbridge"},{"id":"e981","day":28,"season":1,"sday":28,"kind":"campfire","imp":3,"text":"Isolde laughs at one of Ash's jokes, then looks annoyed about it.","heroes":["h12","h18"],"parties":["p1"],"loc":"carrbridge"},{"id":"e987","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"MARKET WEEK: 14 hauls sold across the realm, 1,072 silver all told. Biggest haul: Brix, 284 silver in Carrbridge. Back up from the deep: The Gravediggers of Ironhaven (3 days in the Ashveil Crypts), The Lantern of Carrbridge (3 days in the Ashveil Crypts).","heroes":["h1","h8","h4"],"parties":["p2","p1"]},{"id":"e993","day":29,"season":1,"sday":29,"kind":"ambush","imp":3,"text":"On the road to Bleakmarsh, the Lantern of Carrbridge is routed by 2 Swamp Trolls and 2 Bog Crawlers. Isolde hasn't said a word since.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"bleakmarsh","fight":"f66","foes":["swamp_troll","bog_crawler","bog_crawler"],"where":"on the road to Bleakmarsh","won":false,"close":true,"shape":"place","reworded":15,"wx":"fog"},{"id":"e1007","day":29,"season":1,"sday":29,"kind":"ability","imp":2,"text":"A line of nuns on the road past Bleakmarsh ask Isolde to see them over the hill. Isolde does, singing all three of their hymns badly. They give 15 silver and a long list of corrections.","heroes":["h18"],"parties":["p1"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true,"wx":"fog"},{"id":"e1009","day":29,"season":1,"sday":29,"kind":"campfire","imp":2,"text":"Pickles offers Isolde the dry side of the tent. Isolde accepts, suspiciously.","heroes":["h4","h18"],"parties":["p1"],"loc":"bleakmarsh","wx":"fog"},{"id":"e1029","day":30,"season":1,"sday":30,"kind":"journey","imp":3,"text":"The Gravediggers of Ironhaven and The Lantern of Carrbridge share the road to Thornmere Ruins. By the second milestone they've agreed on nothing, least of all Quill's terrible singing.","heroes":["h8","h15","h2","h11","h4","h18","h12"],"parties":["p2","p1"]},{"id":"e1089","day":31,"season":2,"sday":1,"kind":"talent","imp":2,"text":"A Carrbridge kid asks to hit Ash's shield with a stick. Twenty minutes later there is a queue. (Hard to Dent, if anyone's asking.)","heroes":["h12"],"parties":["p1"],"loc":"carrbridge","skill":"hard_to_dent"},{"id":"e1097","day":31,"season":2,"sday":1,"kind":"argument","imp":2,"text":"Ash says one thing too many about the ethics of looting bodies. Pickles says two.","heroes":["h12","h4"],"parties":["p1"]},{"id":"e1098","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Pickles and Isolde have shared a month of roads in The Lantern of Carrbridge. Ask either one about the other and settle in for a story.","heroes":["h4","h18"],"parties":["p1"],"loc":"carrbridge"},{"id":"e1108","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Lantern of Carrbridge stands before the league and swears it: to die rich. The Annals are watching.","heroes":["h4","h18","h12"],"parties":["p1"]},{"id":"e1131","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Isolde stops at a farmhouse near Carrbridge to look at a child's fever, and stays until it breaks. A small House Calls, cast without looking up.","heroes":["h18"],"parties":["p1"],"loc":"carrbridge","skill":"house_calls","wx":"rain"},{"id":"e1149","day":33,"season":2,"sday":3,"kind":"ambush","imp":2,"text":"Two Wolves come looking for an easy meal on the road to Ashfen and find the Lantern of Carrbridge instead. Hammer Down, from Ash, was the last thing the wolf saw. Pickles saved Bless for when it mattered. Loot: 2 pelts, 3 fangs & claws.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"kingsroad","fight":"f73","foes":["wolf","wolf"],"where":"on the road to Ashfen","won":true,"close":false,"shape":"foe","reworded":-43,"wx":"rain"},{"id":"e1150","day":33,"season":2,"sday":3,"kind":"road","imp":3,"text":"A veteran gambler on the road to Ashfen gives Isolde a worn knucklebone, says it has never lost and always lost, and waves them off before an answer comes.","heroes":["h18","h12","h4"],"parties":["p1"],"road":"ashfen~carrbridge","road_rec":"r245"},{"id":"e1160","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Pickles loses an arm-wrestle at the Ashfen tavern to a grandmother, then shakes her hand out of respect. Arm Wrestler, the way the drill-yards teach it.","heroes":["h4"],"parties":["p1"],"loc":"ashfen","skill":"arm_wrestler"},{"id":"e1173","day":34,"season":2,"sday":4,"kind":"curse","imp":2,"text":"Pickles snaps at a barkeep over nothing, then stares at the Hound's Collar for an hour. The curse is winning, for now.","heroes":["h4"],"parties":["p1"],"loc":"ashfen"},{"id":"e1178","day":34,"season":2,"sday":4,"kind":"talent","imp":1,"text":"Isolde checks every wound in the crew, one by one, whether its owner likes it or not. They heal anyway.","heroes":["h18"],"parties":["p1"],"loc":"ashveil_crypts","skill":"house_calls"},{"id":"e1191","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Pickles and Ash see in a month of The Lantern of Carrbridge by splitting the last good bottle. Nobody else is offered any.","heroes":["h4","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1193","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Isolde and Ash have a month of roads behind them in The Lantern of Carrbridge, and a dozen stories nobody else is allowed to tell.","heroes":["h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1197","day":35,"season":2,"sday":5,"kind":"curse","imp":5,"text":"Ash has had enough. One night Ash prises the Hound's Collar out of Pickles's grip and buries it at a crossroads. Pickles weeps, then sleeps for the first time in weeks.","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1211","day":35,"season":2,"sday":5,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into the Ashveil Crypts, mostly explored (75%), map in hand.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1245","day":36,"season":2,"sday":6,"kind":"fight","imp":1,"text":"The Lantern of Carrbridge gets the better of a Bone Construct in the articulator's hall on floor 3 of the Ashveil Crypts. The fight turned on Pickles' Smite. Loot: 13 bones. Pickles, who has been afraid of the dead since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f87","foes":["bone_construct"],"where":"in the articulator's hall on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-11},{"id":"e1246","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a steady pace: 1 room (the articulator's hall).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e1277","day":37,"season":2,"sday":7,"kind":"gear","imp":1,"text":"In the Lorne vault on floor 3 of the Ashveil Crypts, Pickles finds Delver's Warden's Girdle and puts it on. Delver's: harder to ambush (+8%).","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1278","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a steady pace: 3 rooms (the gravediggers' bunks, the drowned niches, the Lorne vault).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":2,"wild":[]}},{"id":"e1304","day":37,"season":2,"sday":7,"kind":"talent","imp":2,"text":"Ash knocks on their own breastplate, listens, and nods like a doctor. Ash puts it down to Hard to Dent.","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","skill":"hard_to_dent"},{"id":"e1325","day":38,"season":2,"sday":8,"kind":"fight","imp":2,"text":"Isolde holds the line as the Lantern of Carrbridge survives 3 Risen Dead, a Skeleton Archer and a Bone Construct in the stitching room on floor 3 of the Ashveil Crypts. Isolde's Cleave caught four of them at once. Loot: 20 bones, 6 grave dust, 7 crypt-caps. Ash hates the dead more than anything, and fights through it anyway.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f92","foes":["skeleton_archer","zombie","zombie"],"where":"in the stitching room on floor 3 of the Ashveil Crypts","won":true,"close":true,"shape":"hero","reworded":-25},{"id":"e1329","day":38,"season":2,"sday":8,"kind":"boss","imp":5,"text":"Nine rounds in, the Lantern of Carrbridge puts an end to 2 Bone Constructs and Vessimir the Unburied at the bottom of the Ashveil Crypts. The fight ended in a flash of Pickles' Smite. Isolde should have gone down. Lay on Hands said otherwise. Pickles accounted for 3 of them, mostly with Banishing Rite. Battle Cry, from Ash, at exactly the right moment. Loot: 96 silver each, 6 ectoplasm, 13 grave dust.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f93","foes":["necromancer","bone_construct","bone_construct"],"where":"at the bottom of The Ashveil Crypts","won":true,"close":true,"shape":"close","reworded":-25},{"id":"e1331","day":38,"season":2,"sday":8,"kind":"treasure","imp":2,"text":"Vessimir the Unburied had been saving. The savings come to 11 gold pieces and 6 silver, and are now somebody else's.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","in_fight":"f93"},{"id":"e1332","day":38,"season":2,"sday":8,"kind":"gear","imp":4,"text":"Out of the Ashveil Crypts comes Ash, and with Ash comes a pale mask with a calm, sleeping face from the lowest crypt: one of a kind, and not yet understood.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e1333","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a cautious pace: 2 rooms (the stitching room, the lowest crypt).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":2,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common","unique"],"fears":2,"wild":[]}},{"id":"e1334","day":38,"season":2,"sday":8,"kind":"delve_done","imp":3,"text":"The Lantern of Carrbridge comes out into the light after 4 days with the dark still in every seam. They worked through 6 rooms, reached the deepest floor, found the Lorne vault, the stitching room and the lowest crypt, mapped 73% of it and came away with 574 silver between them. The Ashveil Crypts, all crews together: mostly explored (85%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","days":4,"bottom":true,"rooms":["the Lorne vault","the stitching room"],"gold":574,"turn":"done"},{"id":"e1357","day":38,"season":2,"sday":8,"kind":"big_move","imp":4,"text":"Nine rounds in, the Lantern of Carrbridge puts an end to 2 Bone Constructs and Vessimir the Unburied at the bottom of the Ashveil Crypts. On the table: Isolde +106 renown (14th to 7th), Ash +105 (19th to 8th) and Pickles +104 (10th to 4th). The Lantern of Carrbridge +172 party renown (4th to 2nd among the crews).","heroes":["h18","h12","h4"],"parties":["p1"],"cause":"e1329","moves":[{"hero":"h18","gain":106,"from":14,"to":7},{"hero":"h12","gain":105,"from":19,"to":8},{"hero":"h4","gain":104,"from":10,"to":4}],"party_moves":[{"party":"p1","gain":172,"from":4,"to":2}],"fight":"f93"},{"id":"e1397","day":39,"season":2,"sday":9,"kind":"gift","imp":2,"text":"Pickles admired Isolde's Bell off a Cat's Collar one too many times. Now it's Pickles's.","heroes":["h18","h4"],"parties":["p1"],"loc":"ashfen"},{"id":"e1398","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Pickles lights a candle at the Ashfen temple for everyone in the party, by name. Not On My Watch: one of the things Pickles learned the long way round.","heroes":["h4"],"parties":["p1"],"loc":"ashfen","skill":"not_on_my_watch"},{"id":"e1432","day":40,"season":2,"sday":10,"kind":"meet","imp":1,"text":"Isolde and Brix swap stories in Bleakmarsh while The Lantern of Carrbridge and Azure Edge swap rumours.","heroes":["h4","h18","h12","h3","h9","h1","h5"],"parties":["p1","p3"],"loc":"bleakmarsh"},{"id":"e1433","day":40,"season":2,"sday":10,"kind":"ability","imp":2,"text":"Isolde and Pickles escort a family of travellers past Bleakmarsh. Nothing happens, which is the point. They're paid 29 silver for it.","heroes":["h18","h4"],"parties":["p1"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e1439","day":40,"season":2,"sday":10,"kind":"talent","imp":2,"text":"Pickles challenges Ash to an arm-wrestle by the fire. It's a draw. Both agree it was a draw. Both are lying.","heroes":["h4","h12"],"parties":["p1"],"loc":"bleakmarsh","skill":"arm_wrestler"},{"id":"e1460","day":41,"season":2,"sday":11,"kind":"ambush","imp":2,"text":"The Lantern of Carrbridge makes it five wins running, handling 2 Will-o'-Wisps and a Bog Crawler at their camp in Thornmere Ruins, in the middle of the night. Everything after Ash's Anvil Drop went right. Oath of Light did more for this fight than the scoreboard shows. That was Isolde. Loot: 3 chitin, 2 bog crawler claws.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f99","foes":["bog_crawler","wisp","wisp"],"where":"at their camp in Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"streak","reworded":-29,"wx":"storm"},{"id":"e1470","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Lantern of Carrbridge sets their sights for the season: to finish the season as one of the top three parties.","heroes":["h4","h18","h12"],"parties":["p1"]},{"id":"e1482","day":42,"season":2,"sday":12,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into Thornmere Ruins, partly explored (59%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1483","day":42,"season":2,"sday":12,"kind":"night","imp":2,"text":"Isolde follows strange lights away from the camp on floor 3 of Thornmere Ruins, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1510","day":42,"season":2,"sday":12,"kind":"argument","imp":2,"text":"Pickles and Ash spend supper disagreeing about Ash's cooking, politely at first.","heroes":["h4","h12"],"parties":["p1"]},{"id":"e1526","day":43,"season":2,"sday":13,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of Thornmere Ruins at a steady pace: 2 rooms (the sunken stair, the hag's larder).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"rain"},{"id":"e1563","day":44,"season":2,"sday":14,"kind":"sniped","imp":3,"text":"Thornmere Ruins is quieter now, because The Gravediggers of Ironhaven killed Mother Thornmere today, and The Lantern of Carrbridge and Azure Edge all hear it by noon and change their plans to suit.","heroes":["h1","h11","h12","h15","h18","h2","h3","h4","h5","h8","h9"],"parties":["p1","p2","p3"],"loc":"thornmere_ruins","snipers":["h8","h15","h2","h11"],"where":"many","boss":"Mother Thornmere","in_fight":"f103"},{"id":"e1568","day":44,"season":2,"sday":14,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of Thornmere Ruins at a cautious pace: 2 rooms (the gallery of charms, the hag's still room).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"size":3,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":1,"wild":[]}},{"id":"e1601","day":45,"season":2,"sday":15,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of Thornmere Ruins at a steady pace: 1 room (the priests' cells).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1602","day":45,"season":2,"sday":15,"kind":"delve_done","imp":3,"text":"Thornmere Ruins, 4 days on: The Lantern of Carrbridge comes up blinking at the daylight. They came across the hag's larder and the hag's still room, went as deep as the place goes, put 8% of it on paper, worked through 5 rooms and came away with 70 silver between them. No boss, but the place paid. All the crews' maps laid side by side say Thornmere Ruins is mostly explored (86%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","days":4,"bottom":true,"rooms":["the hag's larder","the hag's still room"],"gold":70,"turn":"floor"},{"id":"e1650","day":46,"season":2,"sday":16,"kind":"journey","imp":2,"text":"Azure Edge and The Lantern of Carrbridge share the road to Bleakmarsh. By the second milestone they've agreed on nothing, least of all Duren's terrible singing.","heroes":["h3","h9","h1","h5","h4","h18","h12"],"parties":["p3","p1"]},{"id":"e1652","day":46,"season":2,"sday":16,"kind":"ability","imp":2,"text":"Bandits watch Isolde lead a line of pilgrims past Bleakmarsh, look at his sword, and stay sitting down. At the shrine the pilgrims hand over 35 silver and a blessing apiece.","heroes":["h18"],"parties":["p1"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e1675","day":47,"season":2,"sday":17,"kind":"road","imp":3,"text":"Tilly Drum sings a ballad of Pickles's journey on the road. It is almost accurate, and nearly in tune.","heroes":["h4","h12","h18"],"parties":["p1"],"road":"bleakmarsh~carrbridge","traveller":"off_key","road_rec":"r328"},{"id":"e1694","day":47,"season":2,"sday":17,"kind":"talent","imp":2,"text":"Pickles wins a sack of turnips in an arm-wrestling bout at the Carrbridge fair. Arm Wrestler, the way the drill-yards teach it.","heroes":["h4"],"parties":["p1"],"loc":"carrbridge","skill":"arm_wrestler"},{"id":"e1764","day":50,"season":2,"sday":20,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into Thornmere Ruins, mostly explored (86%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1773","day":50,"season":2,"sday":20,"kind":"talent","imp":2,"text":"Ash trips on a step and Pickles is already there with a bandage before Ash hits the floor. Not On My Watch: one of the things Pickles learned the long way round.","heroes":["h4","h12"],"parties":["p1"],"loc":"thornmere_ruins","skill":"not_on_my_watch"},{"id":"e1781","day":50,"season":2,"sday":20,"kind":"campfire","imp":2,"text":"Ash notices Pickles has the same boots, a size bigger. Neither knows what to do with this.","heroes":["h4","h12"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e1801","day":51,"season":2,"sday":21,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the lamp-lit passage, the brewhouse, a hidden room behind the brewhouse).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1821","day":51,"season":2,"sday":21,"kind":"big_move","imp":4,"text":"Nhalthane Who Was Promised is dead! It falls to Ash, Pickles, Isolde in Thornmere Ruins. On the table: Ash +135 renown (12th to 1st), Isolde +109 (9th to 4th) and Pickles +103 (8th to 3rd). The Lantern of Carrbridge +142 party renown (3rd to 1st among the crews).","heroes":["h12","h18","h4"],"parties":["p1"],"cause":"e1792","moves":[{"hero":"h12","gain":135,"from":12,"to":1},{"hero":"h18","gain":109,"from":9,"to":4},{"hero":"h4","gain":103,"from":8,"to":3}],"party_moves":[{"party":"p1","gain":142,"from":3,"to":1}],"fight":"f116"},{"id":"e1835","day":52,"season":2,"sday":22,"kind":"fight","imp":1,"text":"The Lantern of Carrbridge handles 2 Will-o'-Wisps and a Siren in the choir loft on floor 2 of Thornmere Ruins without much fuss. Isolde's Cleave took down two will-o'-wisps at once. Inspire did more for this fight than the scoreboard shows. That was Ash. Loot: 4 bottled wisplight, 2 wisp sugar, 5 trinkets.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f125","foes":["wisp","wisp","siren"],"where":"in the choir loft on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e1836","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the choir loft, the cloister garth, the dormitory).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e1872","day":53,"season":2,"sday":23,"kind":"fight","imp":2,"text":"It's 2 Drakes, a Bog Crawler and a Swamp Troll against the Lantern of Carrbridge in the undercroft arches on floor 2 of Thornmere Ruins, and it isn't close. The last bog crawler bolts. Isolde should have gone down. Lay on Hands said otherwise. Loot: 13 silver each, 2 drake scales, 4 drake flanks.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f131","foes":["drake","bog_crawler","drake"],"where":"in the undercroft arches on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-27},{"id":"e1874","day":53,"season":2,"sday":23,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the reed-choked treasury, a walled-up room beside the reed-choked treasury, the undercroft arches).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":3,"wild":[]}},{"id":"e1915","day":54,"season":2,"sday":24,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of Thornmere Ruins at a cautious pace: 1 room (the ossuary).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1916","day":54,"season":2,"sday":24,"kind":"delve_done","imp":3,"text":"The Lantern of Carrbridge comes out after 5 days, and the first thing anyone wants is bread. They cleared 10 rooms, went as deep as the place goes, mapped 30% of it, came across the lamp-lit passage, a hidden room behind the brewhouse, the dormitory and 3 more good rooms and split 592 silver on the way up. Thornmere Ruins is picked clean (100%) now, with the league's pencil marks all over it.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","days":5,"bottom":true,"rooms":["the lamp-lit passage","a hidden room behind the brewhouse"],"gold":592,"turn":"floor","wx":"storm"},{"id":"e1954","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"Ash slides down a muddy bank near Bleakmarsh on their armoured backside and arrives first. Somebody asks how. 'Hard to Dent,' says Ash.","heroes":["h12"],"parties":["p1"],"loc":"bleakmarsh","skill":"hard_to_dent"},{"id":"e1956","day":55,"season":2,"sday":25,"kind":"talent","imp":1,"text":"Isolde hums a hymn at walking pace. By noon three strangers are humming it too.","heroes":["h18"],"parties":["p1"],"loc":"bleakmarsh","skill":"pilgrims_escort"},{"id":"e2013","day":57,"season":2,"sday":27,"kind":"road","imp":3,"text":"Wilhelmina Pott tells Ash what the students say about Cragtooth Warren, and that nobody has been brave enough to check.","heroes":["h12","h18","h4"],"parties":["p1"],"road":"carrbridge~saltmarrow","traveller":"truant_scholars","road_rec":"r396"},{"id":"e2020","day":57,"season":2,"sday":27,"kind":"ability","imp":2,"text":"A pedlar with a bad leg and a worse donkey asks Isolde to walk with them past Carrbridge. Isolde carries the donkey's load half the way, learns a lot about pots, and is paid 19 silver at the gate.","heroes":["h18"],"parties":["p1"],"loc":"carrbridge","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e2021","day":57,"season":2,"sday":27,"kind":"talent","imp":1,"text":"Pickles makes the party walk in a tighter group today. Nobody quite knows why. Nobody argues. Not On My Watch all the way, Pickles insists.","heroes":["h4"],"parties":["p1"],"loc":"carrbridge","skill":"not_on_my_watch"},{"id":"e2098","day":60,"season":2,"sday":30,"kind":"road","imp":3,"text":"A gannet drops something that gleams on the deck of the Gannet ferry, and Ash finds a small pearl the size of a pea.","heroes":["h12","h18","h4"],"parties":["p1"],"road":"saltcliffs~saltmarrow","road_rec":"r410"},{"id":"e2119","day":60,"season":2,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Lantern of Carrbridge set out to finish the season as one of the top three parties, and the final table says they made it. XP: Pickles +800 (level 16!), Isolde +800 (level 16!), Ash +800 (level 16!).","heroes":[],"parties":["p1"],"xp":{"h4":800,"h18":800,"h12":800}},{"id":"e2146","day":61,"season":3,"sday":1,"kind":"road","imp":3,"text":"Pickles drops 1 copper in the dish of the Shrine of Quiet Names and feels a hand rest on their shoulder for a breath. No one is behind them.","heroes":["h4","h12","h18"],"parties":["p1"],"road":"ashfen~ashveil_crypts","road_rec":"r423"},{"id":"e2147","day":61,"season":3,"sday":1,"kind":"talent","imp":1,"text":"Pickles rings the cat's bell once at bedtime. A fox looks in from the dark, decides it isn't for foxes, and leaves.","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2171","day":61,"season":3,"sday":1,"kind":"tarot","imp":2,"text":"The Lantern of Carrbridge sit in a ring while Isolde turns the Pressed-Leaf Tarot for all of them before the Ashveil Crypts: the Five of Cups, the Six of Cups and the Five of Pentacles. Not a spread anyone wants.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","reading":"r431"},{"id":"e2190","day":62,"season":3,"sday":2,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into the Ashveil Crypts, untouched (0%), map in hand.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2191","day":62,"season":3,"sday":2,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 1 of the Ashveil Crypts at a steady pace: 4 rooms (the sunken causeway, the lych-gate, the gatekeeper's lodge and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":2,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":6,"wild":[]}},{"id":"e2211","day":63,"season":3,"sday":3,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 1 of the Ashveil Crypts at a steady pace: 4 rooms (the grave-goods store, the chantry, the reliquary and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2231","day":64,"season":3,"sday":4,"kind":"fight","imp":1,"text":"The Lantern of Carrbridge defeats 2 Risen Dead and a Skeleton in the bier hall on floor 1 of the Ashveil Crypts. Ash closed it out with Anvil Drop on the skeleton. Isolde's Oath of Light kicked in when it counted. Loot: 3 bones, 2 crypt-caps, 3 grave dust. Pickles, who has been afraid of the dead since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f147","foes":["zombie","skeleton","zombie"],"where":"in the bier hall on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"plain","wx":"fog"},{"id":"e2232","day":64,"season":3,"sday":4,"kind":"fight","imp":1,"text":"Two Skeleton Archers and a Skeleton fall to the Lantern of Carrbridge in the choir loft on floor 1 of the Ashveil Crypts. Pickles sent Expose Weakness across the fight. The skeleton didn't come back from it. Loot: 8 bones, 2 crypt-caps. Ash hates the dead more than anything, and fights through it anyway.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f148","foes":["skeleton_archer","skeleton","skeleton_archer"],"where":"in the choir loft on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-2,"wx":"fog"},{"id":"e2233","day":64,"season":3,"sday":4,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 1 of the Ashveil Crypts at a steady pace: 4 rooms (the mason's yard, the bier hall, the choir loft and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":7,"wild":[]},"wx":"fog"},{"id":"e2255","day":65,"season":3,"sday":5,"kind":"fight","imp":2,"text":"With Isolde hitting hardest, the Lantern of Carrbridge sees off 2 Skeletons, Risen Dead and a Skeleton Archer in the nave on floor 1 of the Ashveil Crypts. Everything after Isolde's Cleave went right. Loot: 3 grave dust, 10 bones, 2 trinkets.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f152","foes":["zombie","skeleton","skeleton"],"where":"in the nave on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-29,"wx":"fog"},{"id":"e2256","day":65,"season":3,"sday":5,"kind":"gear","imp":1,"text":"In a sealed space off the nave on floor 1 of the Ashveil Crypts, Ash finds a pair of Sturdy Fingerless Gloves and puts them on. Sturdy: a little better protected (+1.5 armour).","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2257","day":65,"season":3,"sday":5,"kind":"fight","imp":2,"text":"In the ossuary on floor 1 of the Ashveil Crypts, the Lantern of Carrbridge beats 4 Risen Dead and a Skeleton Archer. The fight was over the moment Ash's Hammer Down landed on the risen dead. Loot: 4 remains, 3 grave dust, 3 bones.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f153","foes":["zombie","zombie","zombie"],"where":"in the ossuary on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-1,"wx":"fog"},{"id":"e2258","day":65,"season":3,"sday":5,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 1 of the Ashveil Crypts at a steady pace: 4 rooms (the nave, a sealed space off the nave, the candle vault and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["great"],"fears":4,"wild":[]},"wx":"fog"},{"id":"e2278","day":66,"season":3,"sday":6,"kind":"fight","imp":2,"text":"The Lantern of Carrbridge, in fine spirits lately, dispatches 3 Risen Dead and a Skeleton in the coffin racks on floor 1 of the Ashveil Crypts. The fight ended in a flash of Pickles' Banishing Rite. Loot: 2 crypt-caps, 3 bones, 2 trinkets.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f154","foes":["zombie","skeleton","zombie"],"where":"in the coffin racks on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"fog"},{"id":"e2279","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 1 of the Ashveil Crypts at a steady pace: 4 rooms (a hidden room behind the ossuary, a spiral stair behind the ossuary screen, the coffin racks and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":4,"wild":[]},"wx":"fog"},{"id":"e2300","day":66,"season":3,"sday":6,"kind":"bond","imp":3,"text":"The Lantern of Carrbridge and The Gravediggers of Ironhaven are rivals now, starting with Ash and Sela.","heroes":["h12","h2"],"parties":["p1","p2"],"bond":"rivals"},{"id":"e2317","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of the Ashveil Crypts at a cautious pace: 3 rooms (the coffin-makers' yard, the sexton's lodging, the embalming room).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":3,"size":3,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":6,"wild":[]},"wx":"fog"},{"id":"e2318","day":67,"season":3,"sday":7,"kind":"talent","imp":2,"text":"Isolde preaches to the crew about sharing. Ash hands over the last biscuit, shamed.","heroes":["h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","skill":"sermoniser","wx":"fog"},{"id":"e2348","day":68,"season":3,"sday":8,"kind":"gear","imp":1,"text":"In a hidden room behind the embalming room on floor 2 of the Ashveil Crypts, Ash finds a Grave-Blessed Silver Ring and puts it on. Grave-Blessed: much braver (+7 nerve).","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2349","day":68,"season":3,"sday":8,"kind":"fight","imp":1,"text":"The Lantern of Carrbridge sends 3 Skeletons back to their rest in the skeletons' quiet corner on floor 2 of the Ashveil Crypts. Somewhere around Ash's Anvil Drop, the other side stopped believing. Loot: 8 bones, 2 trinkets.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f163","foes":["skeleton","skeleton","skeleton"],"where":"in the skeletons' quiet corner on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-19,"wx":"fog"},{"id":"e2350","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of the Ashveil Crypts at a steady pace: 4 rooms (a hidden room behind the embalming room, the gravediggers' bunks, the cold room and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great","cosmetic"],"fears":4,"wild":[]},"wx":"fog"},{"id":"e2352","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Isolde freezes a pond's skin with a word and cuts a fishing hole. Dinner comes up through it. One quiet Ice Fishing, and done.","heroes":["h18"],"parties":["p1"],"loc":"ashveil_crypts","skill":"ice_fishing","wx":"fog"},{"id":"e2353","day":68,"season":3,"sday":8,"kind":"night","imp":2,"text":"A hooded stranger shares The Lantern of Carrbridge's fire on floor 2 of the Ashveil Crypts, eats half the stew, and says something very specific about Goblin Camp before leaving.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2377","day":69,"season":3,"sday":9,"kind":"gear","imp":1,"text":"In a walled-up room beside the mourners' kitchen on floor 2 of the Ashveil Crypts, Pickles finds a Lucky Bearskin Mantle and puts it on. Lucky: finds weak spots a little more often (+2 crit).","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2378","day":69,"season":3,"sday":9,"kind":"famous_trap","imp":3,"text":"The Ninth Step claims Ash in the Ashveil Crypts, the first it has caught since the new tenant moved in.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2379","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of the Ashveil Crypts at a steady pace: 4 rooms (the mourners' kitchen, a walled-up room beside the mourners' kitchen, The Ninth Step and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":2,"traps":1,"sprung":2,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great","common"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e2436","day":70,"season":3,"sday":10,"kind":"party_life","imp":3,"text":"The Ashveil Crypts sends word that Ash sat down on floor 2 and stayed sat, so The Lantern of Carrbridge turns back.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","refusal":"h12","wx":"fog"},{"id":"e2437","day":70,"season":3,"sday":10,"kind":"delve_done","imp":3,"text":"After 9 days underground, The Lantern of Carrbridge climbs back into the open air, gulping it down like water. They took 31 rooms off the map's blank side, reached floor 2, turned up the gatekeeper's lodge, the grave-goods store, the chantry and 8 more good rooms, put 50% of it on paper, disarmed 1 trap, split 352 silver on the way up and turned back when one of them would go no further. The Ashveil Crypts now stands partly explored (46%), every crew's chalk marks counted.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","days":9,"bottom":false,"rooms":["the gatekeeper's lodge","the grave-goods store"],"gold":352,"turn":"refused","wx":"fog"},{"id":"e2474","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"The Ashfen shrine-keeper asks Isolde to bless the road out of town. He does, briefly. Chalk it up to The Pilgrims' Escort.","heroes":["h18"],"parties":["p1"],"loc":"ashfen","skill":"pilgrims_escort","wx":"fog"},{"id":"e2480","day":71,"season":3,"sday":11,"kind":"vow_progress","imp":3,"text":"The Lantern of Carrbridge swore to die rich on day 1 of season 2. With 3,315 silver earned since, they're rich. Now they just have to stay that way until the age ends.","heroes":["h4","h18","h12"],"parties":["p1"],"cause":"e1108"},{"id":"e2481","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Lantern of Carrbridge settles on a goal: to find a relic of the old world.","heroes":["h4","h18","h12"],"parties":["p1"]},{"id":"e2511","day":72,"season":3,"sday":12,"kind":"road","imp":4,"text":"At a crossing on the road to Bleakmarsh an old stone has a count cut into it: every traveller who has ever passed. As Isolde reads, a fresh stroke appears for them. It is the hundred-thousandth. The stone hums, and a hidden hollow gives up 35 silver.","heroes":["h18","h12","h4"],"parties":["p1"],"road":"ashfen~bleakmarsh","road_rec":"r483"},{"id":"e2519","day":72,"season":3,"sday":12,"kind":"ability","imp":2,"text":"Isolde finds two lost children on the road past Bleakmarsh and walks them home. Their grandmother pays 33 silver and shows Isolde the shortcut nobody else knows.","heroes":["h18"],"parties":["p1"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e2527","day":73,"season":3,"sday":13,"kind":"road","imp":2,"text":"The Muddy Boot Pack have built a bridge across a ditch for the first time, and Snaggle proudly walks Pickles over it. It is one plank, and the plank is a door.","heroes":["h4","h12","h18"],"parties":["p1"],"road":"bleakmarsh~thornmere_ruins","traveller":"muddy_boot","road_rec":"r485"},{"id":"e2561","day":74,"season":3,"sday":14,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into Thornmere Ruins, mostly explored (68%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e2564","day":74,"season":3,"sday":14,"kind":"fight","imp":2,"text":"The Lantern of Carrbridge runs into 3 Will-o'-Wisps and a Bog Crawler in the reed beds on floor 1 of Thornmere Ruins and comes out on top. The hit of the day was Isolde's Cleave on the bog crawler. Ask the others what won it: Ash's Inspire. Loot: 2 wisp sugar, 4 bottled wisplight, 3 chitin.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f178","foes":["wisp","wisp","bog_crawler"],"where":"in the reed beds on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-23},{"id":"e2565","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the reed beds, the wellhead).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2594","day":75,"season":3,"sday":15,"kind":"fight","imp":2,"text":"Ash keeps everyone up as the Lantern of Carrbridge defeats 2 Will-o'-Wisps, a Bog Crawler and a Swamp Troll in the drowned nave on floor 1 of Thornmere Ruins. Ash's Anvil Drop caught the swamp troll square. It stayed down. Isolde's Cleave did the damage (2 times). Loot: 18 silver each, 2 chitin, 2 wisp sugar.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f180","foes":["wisp","bog_crawler","wisp"],"where":"in the drowned nave on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-25},{"id":"e2596","day":75,"season":3,"sday":15,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of Thornmere Ruins at a steady pace: 2 rooms (the drowned nave, the abbot's lodging).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2616","day":75,"season":3,"sday":15,"kind":"argument","imp":2,"text":"It starts with Isolde's habit of humming during ambushes. It ends with Isolde and Pickles sleeping on opposite sides of the fire.","heroes":["h18","h4"],"parties":["p1"]},{"id":"e2630","day":76,"season":3,"sday":16,"kind":"gear","imp":1,"text":"In the lamp-lit passage on floor 2 of Thornmere Ruins, Isolde finds a Copper Band of the Long Night and puts it on. Of the Long Night: much braver (+5 nerve).","heroes":["h18"],"parties":["p1"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2631","day":76,"season":3,"sday":16,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the lamp-lit passage, the brewhouse, a hidden room behind the brewhouse).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great","common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2678","day":77,"season":3,"sday":17,"kind":"fight","imp":1,"text":"In the choir loft on floor 2 of Thornmere Ruins, 2 Will-o'-Wisps and a Siren get in the Lantern of Carrbridge's way, briefly. The final blow was Ash's Anvil Drop. Loot: 2 bottled wisplight, 4 wisp sugar, 3 trinkets.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f183","foes":["wisp","wisp","siren"],"where":"in the choir loft on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-12,"wx":"fog"},{"id":"e2679","day":77,"season":3,"sday":17,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of Thornmere Ruins at a cautious pace: 3 rooms (the choir loft, the cloister garth, the dormitory).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e2713","day":78,"season":3,"sday":18,"kind":"delve_done","imp":3,"text":"The Lantern of Carrbridge comes out into the light after 5 days with the dark still in every seam. They put 40% of it on paper, made it to floor 2, cleared 10 rooms, came across the lamp-lit passage, the brewhouse, a hidden room behind the brewhouse and 1 more good room, came away with 232 silver between them and turned back because their nerves were fraying. Pin it to the board: Thornmere Ruins is mostly explored (84%).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"thornmere_ruins","days":5,"bottom":false,"rooms":["the lamp-lit passage","the brewhouse"],"gold":232,"turn":"nerve","wx":"fog"},{"id":"e2747","day":79,"season":3,"sday":19,"kind":"ability","imp":2,"text":"Bandits watch Isolde lead a line of pilgrims past Bleakmarsh, look at his sword, and stay sitting down. At the shrine the pilgrims hand over 25 silver and a blessing apiece.","heroes":["h18"],"parties":["p1"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true,"wx":"storm"},{"id":"e2788","day":80,"season":3,"sday":20,"kind":"argument","imp":4,"text":"Pickles and Ash have had the same argument three times now. This time Pickles threw a boot. The Lantern of Carrbridge is splitting into camps.","heroes":["h4","h12"],"parties":["p1"]},{"id":"e2808","day":81,"season":3,"sday":21,"kind":"night","imp":2,"text":"Something sings in the dark in the Ashveil Crypts. Ash goes to look and comes back with a trinket and a very quiet manner.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2821","day":81,"season":3,"sday":21,"kind":"meet","imp":2,"text":"The Lantern of Carrbridge runs into The White Quills on the road between Ashfen and the Ashveil Crypts. Stories are exchanged, most of them exaggerated.","heroes":["h4","h18","h12","h7","h13"],"parties":["p1","p5"],"loc":"ashfen"},{"id":"e2840","day":82,"season":3,"sday":22,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into the Ashveil Crypts, partly explored (46%), map in hand.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2841","day":82,"season":3,"sday":22,"kind":"night","imp":2,"text":"Isolde tells a ghost story by the fire on floor 2 of the Ashveil Crypts. Pickles insists on keeping the fire going until dawn. For warmth.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2855","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Isolde shares supper with two pilgrims and their goat. The goat eats Pickles's bootlace. The Pilgrims' Escort: one of the things Isolde learned the long way round.","heroes":["h18","h4"],"parties":["p1"],"loc":"ashveil_crypts","skill":"pilgrims_escort"},{"id":"e2865","day":83,"season":3,"sday":23,"kind":"fight","imp":3,"text":"Three Bone Constructs and Risen Dead stir in the crossing of galleries on floor 2 of the Ashveil Crypts, and the Lantern of Carrbridge makes short work of them for good. Four of them felt Isolde's Cleave in the same breath. Loot: 35 bones, 2 crypt-caps. Pickles hates the dead more than anything, and fights through it anyway.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f196","foes":["bone_construct","bone_construct","bone_construct"],"where":"in the crossing of galleries on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-28},{"id":"e2866","day":83,"season":3,"sday":23,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of the Ashveil Crypts at a steady pace: 2 rooms (the chaplain's cell, the crossing of galleries).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2867","day":83,"season":3,"sday":23,"kind":"talent","imp":2,"text":"Pickles counts heads at camp. Twice. Then a third time, under their breath. That's Not On My Watch for you.","heroes":["h4"],"parties":["p1"],"loc":"ashveil_crypts","skill":"not_on_my_watch"},{"id":"e2868","day":83,"season":3,"sday":23,"kind":"night","imp":1,"text":"Something small and clever gets into The Lantern of Carrbridge's camp on floor 2 of the Ashveil Crypts overnight. Ash wakes up 4 silver and 2 rations lighter.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2919","day":84,"season":3,"sday":24,"kind":"fight","imp":1,"text":"The Lantern of Carrbridge dispatches a Wraith in the widows' walk on floor 2 of the Ashveil Crypts without much fuss. Pickles finished it with Banishing Rite, barely looking. Loot: 4 ectoplasm. Ash, who has been afraid of the dead since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f202","foes":["wraith"],"where":"in the widows' walk on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e2920","day":84,"season":3,"sday":24,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 2 of the Ashveil Crypts at a cautious pace: 2 rooms (a stair of black slate with a name cut on every tread, the widows' walk).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2928","day":84,"season":3,"sday":24,"kind":"argument","imp":2,"text":"Pickles and Ash are not speaking. It's about whose turn it was to keep watch. It's never really about whose turn it was to keep watch.","heroes":["h4","h12"],"parties":["p1"]},{"id":"e2930","day":84,"season":3,"sday":24,"kind":"campfire","imp":3,"text":"Pickles lends Isolde a whetstone. It comes back cleaner than it left.","heroes":["h4","h18"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2939","day":85,"season":3,"sday":25,"kind":"wild_room","imp":3,"text":"The wraith of Ashveil's colonnade has stopped pacing after 200 years. Isolde told her the time.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","room":"wild_widow_hour"},{"id":"e2941","day":85,"season":3,"sday":25,"kind":"artifact","imp":3,"text":"Ash pockets a tin crown that tells its wearer who to distrust in the Ashveil Crypts. Ash feels stronger already.","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e2942","day":85,"season":3,"sday":25,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a steady pace: 3 rooms (the family archive, the colonnade of the hour, the Harrow vault).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_widow_hour"]}},{"id":"e2943","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Ash adjusts every strap on Pickles's armour. Pickles can breathe properly for the first time in weeks. Every ironclad learns Armour Fitting sooner or later. Not every ironclad learns it like that.","heroes":["h12","h4"],"parties":["p1"],"loc":"ashveil_crypts","skill":"armour_fitting"},{"id":"e2996","day":86,"season":3,"sday":26,"kind":"fight","imp":1,"text":"Pickles hits hardest as the Lantern of Carrbridge sees off Risen Dead, a Skeleton Archer and a Skeleton in the long gallery on floor 3 of the Ashveil Crypts. Ash called Battle Cry, and the line steadied. Pickles fought like someone with somewhere better to be afterwards. Loot: 2 grave dust, 7 bones.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f207","foes":["zombie","skeleton_archer","skeleton"],"where":"in the long gallery on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-24},{"id":"e2997","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Lantern of Carrbridge works floor 3 of the Ashveil Crypts at a steady pace: 4 rooms (the reliquary passage, the long gallery, the robbers' last dig and 1 more).","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":4,"size":3,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":5,"wild":[]}},{"id":"e3005","day":86,"season":3,"sday":26,"kind":"argument","imp":1,"text":"Ash and Isolde of The Lantern of Carrbridge have a shouting match about Isolde's cooking.","heroes":["h12","h18"],"parties":["p1"]},{"id":"e3007","day":86,"season":3,"sday":26,"kind":"campfire","imp":1,"text":"Pickles tells Ash a terrible joke about Ironclads. Ash has heard worse.","heroes":["h4","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e3028","day":87,"season":3,"sday":27,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts is behind The Lantern of Carrbridge now: 6 days down there, and the sky looks enormous. They mapped 72% of it, got all the way to the bottom, turned up the colonnade of the hour, the Harrow vault, the robbers' last dig and 1 more good room, cleared 11 rooms, took the teeth out of 1 trap, split 94 silver on the way up and turned back because their nerves were fraying. The Ashveil Crypts is mostly explored (65%) now, with the league's pencil marks all over it.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","days":6,"bottom":true,"rooms":["the colonnade of the hour","the Harrow vault"],"gold":94,"turn":"nerve"},{"id":"e3047","day":87,"season":3,"sday":27,"kind":"campfire","imp":1,"text":"Isolde and Ash end up on the same rope across a stream and have to trust each other for a minute.","heroes":["h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e3083","day":88,"season":3,"sday":28,"kind":"talent","imp":2,"text":"Isolde visits the sick on three streets of Ashfen before lunch and is sent off with a basket of eggs.","heroes":["h18"],"parties":["p1"],"loc":"ashfen","skill":"house_calls"},{"id":"e3092","day":89,"season":3,"sday":29,"kind":"curse","imp":4,"text":"Something is wrong with The Lantern of Carrbridge. Since Ash picked up the Whispering Crown, nobody trusts anybody, and Ash won't put it down.","heroes":["h12"],"parties":["p1"],"loc":"ashfen"},{"id":"e3116","day":89,"season":3,"sday":29,"kind":"talent","imp":1,"text":"A spiked trap springs on Ash. The spikes bend. Ash makes a small note for later. (Hard to Dent, if anyone's asking.)","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","skill":"hard_to_dent"},{"id":"e3119","day":89,"season":3,"sday":29,"kind":"campfire","imp":1,"text":"Isolde passes Pickles the salt without being asked. Pickles wonders how Isolde knew.","heroes":["h18","h4"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e3135","day":90,"season":3,"sday":30,"kind":"delve","imp":1,"text":"The Lantern of Carrbridge descends into the Ashveil Crypts, mostly explored (65%), map in hand.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e3136","day":90,"season":3,"sday":30,"kind":"talent","imp":1,"text":"Ash beats the dents out of the whole crew's gear by firelight at the Ashveil Crypts. Nobody sleeps much; everyone wakes up better armoured.","heroes":["h12"],"parties":["p1"],"loc":"ashveil_crypts","skill":"field_forge"},{"id":"e3137","day":90,"season":3,"sday":30,"kind":"night","imp":2,"text":"Something small and clever gets into The Lantern of Carrbridge's camp on floor 2 of the Ashveil Crypts overnight. Pickles wakes up 12 silver and 1 ration lighter.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e3155","day":90,"season":3,"sday":30,"kind":"delve_done","imp":1,"text":"After a day underground, The Lantern of Carrbridge climbs back into the open air, gulping it down like water. They got down to floor 2.","heroes":["h4","h18","h12"],"parties":["p1"],"loc":"ashveil_crypts","days":1,"bottom":false,"rooms":[],"gold":0},{"id":"e3162","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Lantern of Carrbridge came up short: find a relic of the old world (still looking).","heroes":["h4","h18","h12"],"parties":["p1"]},{"id":"e3168","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Lantern of Carrbridge, to die rich (sworn in season 2); Azure Edge, never to pay a toll (sworn in season 1); The Tidal Almanac, never to retreat (sworn in season 2); The Tidal Almanac, to die rich (sworn in season 2); The White Quills, to keep the peace: never draw first on another hero (sworn in season 1); Cobalt Mercy, to die rich (sworn in season 2); Tobias, never to pay a toll (sworn in season 2); Juniper, never to retreat (sworn in season 1). Every one of them held.","heroes":["h10","h6"],"parties":["p1","p3","p4","p5","p6"]}],"roles":{"h18":"Healer","h4":"Leader · Spellcaster","h12":"Face"},"quest":{"what":"Delve","where":"The Ashveil Crypts","why":"the boss is back: about 61 silver a day each, risk slight; the season goal: to find a relic of the old world; Ash's last chance at the dream before the age ends","floor":1,"floors":3},"tactics":{"front":["h18","h12"],"back":["h4"],"plan":"Isolde and Ash hold the front; Pickles casts from behind; Isolde keeps everyone standing.","traits":{"boldness":0.33,"risk":-0.42,"greed":-0.04,"sociability":-0.39,"honor":-0.32,"curiosity":0.07,"temper":0.23,"loyalty":-0.26},"mix":"2 blades, 1 caster","notes":["Mostly steel: slow, sturdy, hard to shift."],"style":["bold","patient","brawlers"],"skills":[{"label":"Damage","skills":[{"hero":"h18","id":"cleave","name":"Cleave","desc":"Hits everything in the front rank.","tags":["rage"],"rank":1,"uses":30},{"hero":"h4","id":"smite","name":"Smite","desc":"Radiant and righteous. Double against the dead.","tags":["holy"],"rank":3,"uses":28},{"hero":"h12","id":"anvil_drop","name":"Anvil Drop","desc":"Brought the anvil. Nobody asked why. Now they know.","tags":["craft"],"rank":3,"uses":19},{"hero":"h4","id":"banishing_rite","name":"Banishing Rite","desc":"Reads the old words. Spirits hate the old words.","tags":["holy","arcane"],"rank":1,"uses":16},{"hero":"h12","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":3,"uses":15},{"hero":"h4","id":"expose_weakness","name":"Expose Weakness","desc":"Points out the soft bit, loudly.","tags":["lore","crit"],"rank":2,"uses":13},{"hero":"h12","id":"flurry","name":"Flurry","desc":"Three cuts in a heartbeat.","tags":["crit"],"rank":1,"uses":7},{"hero":"h4","id":"pan_to_the_face","name":"Pan to the Face","desc":"The frying pan was for cooking. Was.","tags":[],"rank":1,"uses":5},{"hero":"h4","id":"radiance","name":"Radiance","desc":"A flash of holy light, right in the eyes.","tags":["holy"],"rank":1,"uses":2}]},{"label":"Healing","skills":[{"hero":"h18","id":"lay_on_hands","name":"Lay on Hands","desc":"A warm palm, a closed wound.","tags":["holy","heal"],"rank":3,"uses":8},{"hero":"h18","id":"field_dressing","name":"Field Dressing","desc":"Moss, spit and a clean-ish rag.","tags":["heal"],"rank":1,"uses":1}]},{"label":"Defence","skills":[{"hero":"h12","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":2,"uses":28},{"hero":"h12","id":"battle_cry","name":"Battle Cry","desc":"Bellows something inspiring and mostly vowels. Everyone swings harder.","tags":["command","rage"],"rank":2,"uses":26},{"hero":"h18","id":"intercept","name":"Intercept","desc":"Steps in front of the blow meant for a friend.","tags":["guard"],"rank":2,"uses":21},{"hero":"h4","id":"arcane_shield","name":"Arcane Shield","desc":"A shimmer over the whole party.","tags":["arcane","guard"],"rank":1,"uses":20},{"hero":"h18","id":"divine_shield","name":"Divine Shield","desc":"Golden light, briefly.","tags":["holy","guard"],"rank":3,"uses":20},{"hero":"h4","id":"bless","name":"Bless","desc":"Gods go with you. Hit harder.","tags":["holy"],"rank":3,"uses":14}]},{"label":"Tricks","skills":[{"hero":"h18","id":"oath_of_light","name":"Oath of Light","desc":"Says the oath before the first blow. The oath is long. The armour holds.","tags":["holy"],"rank":1,"uses":23},{"hero":"h4","id":"not_on_my_watch","name":"Not On My Watch","desc":"Counts heads before every fight. Likes the number to stay the same.","tags":[],"rank":1,"uses":9},{"hero":"h12","id":"bolted_down","name":"Bolted Down","desc":"Bolts their boots to the floor. Figuratively. Mostly.","tags":["craft"],"rank":1,"uses":2}]},{"label":"Always on","skills":[{"hero":"h4","id":"know_thy_enemy","name":"Know Thy Enemy","desc":"Read the bestiary. Twice.","tags":["lore"],"rank":1,"uses":0},{"hero":"h18","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":2,"uses":0},{"hero":"h18","id":"lucky","name":"Lucky","desc":"Things just work out.","tags":["crit"],"rank":1,"uses":0},{"hero":"h18","id":"dread_plate","name":"Dread Plate","desc":"Black armour. Polished daily, with regret.","tags":["death"],"rank":1,"uses":0},{"hero":"h12","id":"spiked_shield","name":"Spiked Shield","desc":"Bolted a few spikes on. Improved the conversation.","tags":["craft","guard"],"rank":1,"uses":0},{"hero":"h12","id":"riposte","name":"Riposte","desc":"Every miss is an invitation.","tags":["crit"],"rank":1,"uses":0},{"hero":"h12","id":"hard_to_dent","name":"Hard to Dent","desc":"Wears armour so well-made that fights are mostly a rumour.","tags":[],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h4","id":"fencing_lessons","name":"Fencing Lessons","desc":"Teaches the basics. Charges for the advanced.","tags":["crit"],"rank":1,"uses":0},{"hero":"h4","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h4","id":"linguist","name":"Linguist","desc":"Speaks six languages, including Goblin, badly.","tags":["lore","arcane"],"rank":1,"uses":0},{"hero":"h4","id":"arm_wrestler","name":"Arm Wrestler","desc":"Undefeated. Recently.","tags":[],"rank":1,"uses":0},{"hero":"h4","id":"freeze_over","name":"Freeze Over","desc":"Freezes the ford. Everyone walks across.","tags":["ice"],"rank":1,"uses":0},{"hero":"h4","id":"stargazer","name":"Stargazing","desc":"Can find north, the Swan, and the Little Ladle.","tags":["travel","lore"],"rank":1,"uses":0},{"hero":"h18","id":"sermoniser","name":"Sermoniser","desc":"Has a sermon for every occasion, including this one.","tags":["holy"],"rank":2,"uses":0},{"hero":"h18","id":"house_calls","name":"House Calls","desc":"Visits the sick in every town. Starts with the crew.","tags":["heal","holy"],"rank":1,"uses":0},{"hero":"h18","id":"ice_fishing","name":"Ice Fishing","desc":"Cuts a hole, sits, waits, wins.","tags":[],"rank":1,"uses":0},{"hero":"h12","id":"game_hunter","name":"Game Hunter","desc":"Comes back from a short walk with dinner.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h12","id":"tinkerer","name":"Tinkerer","desc":"Takes things apart. Usually puts them back.","tags":["craft","arcane"],"rank":1,"uses":0},{"hero":"h12","id":"field_forge","name":"Field Forge","desc":"Sets up an anvil on any flat rock and mends what the road broke.","tags":["craft"],"rank":1,"uses":0},{"hero":"h12","id":"bulk_trader","name":"Bulk Trader","desc":"Buys a mule. Then another.","tags":["trade","travel"],"rank":1,"uses":0},{"hero":"h12","id":"armour_fitting","name":"Armour Fitting","desc":"Knows what a breastplate should cost. Pays exactly that.","tags":["craft"],"rank":1,"uses":0}]}],"share":[{"hero":"h4","dmg":3661,"healed":0,"taken":70,"kills":21,"row":"back"},{"hero":"h18","dmg":1597,"healed":100,"taken":380,"kills":7,"row":"front"},{"hero":"h12","dmg":2127,"healed":112,"taken":110,"kills":13,"row":"front"}],"ground":{"name":"The Ashveil Crypts","fights":12}},"trophies":[{"boss":"Vessimir the Unburied","monster":"necromancer","place":"The Ashveil Crypts","day":38,"season":2,"fight":"f93"}]};